<?php require_once __DIR__.'/../includes/layout.php'; require_once __DIR__.'/../includes/user.php'; require_once __DIR__.'/../includes/otp.php';
$errors=[]; if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $missing=require_fields($_POST,['full_name','email','username','password','confirm_password','address','place','district','state','country','living_place','working_place','madrasa_id','position_id','terms','captcha']); if($missing)$errors[]='Please complete all required fields.'; if(($_POST['captcha']??'')!=='8')$errors[]='Captcha answer is incorrect.'; if(!filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL))$errors[]='Invalid email.'; if(!valid_username($_POST['username']??''))$errors[]='Invalid username.'; if(find_user_by_email($_POST['email']??''))$errors[]='Email already exists.'; if(find_user_by_username($_POST['username']??''))$errors[]='Username already exists.'; if(($_POST['password']??'')!==($_POST['confirm_password']??''))$errors[]='Passwords do not match.'; $errors=array_merge($errors,password_errors($_POST['password']??'')); if(!$errors){$uid=create_user($_POST); create_otp($uid,$_POST['email'],'email_verify'); $_SESSION['verify_email']=$_POST['email']; redirect('/auth/verify-email.php?sent=1');}}
$mad=db()->query("SELECT id,name FROM madrasas WHERE status='enabled' ORDER BY sort_order,name")->fetchAll(); $pos=db()->query('SELECT id,name FROM positions ORDER BY name')->fetchAll(); auth_header('Create Account'); ?>
<h2 class="brand">Create your secure account</h2><?php foreach($errors as $er):?><div class="alert alert-danger"><?=e($er)?></div><?php endforeach;?>
<form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><?php $fields=['full_name'=>'Full Name','email'=>'Email','username'=>'Username','address'=>'Address','place'=>'Place','district'=>'District','state'=>'State','country'=>'Country','living_place'=>'Living Place','working_place'=>'Working Place','msr_number'=>'MSR Number (Optional)','certificate_number'=>'Certificate Number (Optional)','phone'=>'Phone']; foreach($fields as $n=>$l):?><div class="col-md-6 form-floating"><input class="form-control" id="<?=$n?>" name="<?=$n?>" placeholder="<?=$l?>" <?=in_array($n,['email','username'])?'data-check="'.($n==='email'?'email':'username').'"':''?>><label for="<?=$n?>"><?=$l?></label></div><?php endforeach;?><div class="col-md-6 form-floating"><select class="form-select" name="madrasa_id"><option value="">Choose</option><?php foreach($mad as $m):?><option value="<?=$m['id']?>"><?=e($m['name'])?></option><?php endforeach;?></select><label>Madrasa</label></div><div class="col-md-6 form-floating"><select class="form-select" name="position_id"><option value="">Choose</option><?php foreach($pos as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?></option><?php endforeach;?></select><label>Position</label></div><div class="col-md-6"><input type="password" name="password" id="password" class="form-control" placeholder="Password" data-strength="#strength"><div class="progress mt-2"><div id="strength" class="progress-bar" style="width:0"></div></div></div><div class="col-md-6"><input type="password" name="confirm_password" class="form-control" placeholder="Confirm Password"></div><div class="col-md-6"><input name="captcha" class="form-control" placeholder="Captcha: 3 + 5 = ?"></div><div class="col-12 form-check ms-2"><input class="form-check-input" type="checkbox" name="terms" value="1" id="terms"><label for="terms">I accept the terms</label></div><div class="col-12"><button class="btn btn-premium w-100">Register</button></div></form><p class="mt-3"><a href="login.php">Already registered? Login</a></p><?php auth_footer(); ?>
